import{_ as a}from"./chunks/attachments-overview.CprVzOos.js";import{_ as t,o as r,c as o,a5 as i}from"./chunks/framework.BrSBneze.js";const b=JSON.parse('{"title":"Benchmark overview","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/overview.md","filePath":"getting-started/overview.md","lastUpdated":1788882780000}'),s={name:"getting-started/overview.md"};function n(l,e,d,h,c,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="benchmark-overview" tabindex="-1">Benchmark overview <a class="header-anchor" href="#benchmark-overview" aria-label="Permalink to &quot;Benchmark overview&quot;">​</a></h1><p>HiveBoard evaluates manipulation of mechanisms with constrained motion. A platform may need to rotate a valve about a fixed axis, keep a screw engaged with its thread, align and insert a key, or complete a sequence of dependent actions.</p><figure class="doc-image"><img src="'+a+'" alt="HiveBoard attachments grouped by manipulation category"><figcaption>The HiveBoard attachments shown on the honeycomb base and as isolated mechanisms.</figcaption></figure><h2 id="hardware-and-platform-support" tabindex="-1">Hardware and platform support <a class="header-anchor" href="#hardware-and-platform-support" aria-label="Permalink to &quot;Hardware and platform support&quot;">​</a></h2><h3 id="reproducible-hardware" tabindex="-1">Reproducible hardware <a class="header-anchor" href="#reproducible-hardware" aria-label="Permalink to &quot;Reproducible hardware&quot;">​</a></h3><p>All structural and functional parts are designed for consumer-grade fused-deposition modelling using PLA. The shared press-fit geometry allows laboratories to reproduce the same board without a specialized fixture.</p><h3 id="modular-tasks" tabindex="-1">Modular tasks <a class="header-anchor" href="#modular-tasks" aria-label="Permalink to &quot;Modular tasks&quot;">​</a></h3><p>The seven-cell honeycomb base accepts interchangeable attachments. Modules can be swapped without changing the base, and new tasks can reuse the same mounting interface.</p><h3 id="embodiment-independent-evaluation" tabindex="-1">Embodiment-independent evaluation <a class="header-anchor" href="#embodiment-independent-evaluation" aria-label="Permalink to &quot;Embodiment-independent evaluation&quot;">​</a></h3><p>The protocol treats a platform as an end-effector plus the system that positions and commands it. This keeps the benchmark applicable to fixed-base manipulators, quadruped manipulators, wearable devices, prosthetic hands, and exoskeletons.</p><h3 id="simulation-models" tabindex="-1">Simulation models <a class="header-anchor" href="#simulation-models" aria-label="Permalink to &quot;Simulation models&quot;">​</a></h3><p>The repository includes articulated assets with visual and collision meshes, joint limits, and nominal physical properties. These assets support inspection and integration in common robotics simulators; a separate repository contains the Isaac Lab implementation.</p><h2 id="task-families" tabindex="-1">Task families <a class="header-anchor" href="#task-families" aria-label="Permalink to &quot;Task families&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>What it tests</th><th>Attachments</th></tr></thead><tbody><tr><td>Torque</td><td>Rotational manipulation and force transmission</td><td>Ball valve, ball valve with friction ring, small and large gate valves, circuit breaker</td></tr><tr><td>Precision</td><td>Alignment, threading, insertion, and controlled rotation</td><td>Light bulb, M8 thread, M30 thread, threaded peg insertion</td></tr><tr><td>Composed assembly</td><td>Ordered sequences with stage-wise progress</td><td>Covered button, lock and key, drawer, shock absorber</td></tr></tbody></table><h2 id="what-the-benchmark-reports" tabindex="-1">What the benchmark reports <a class="header-anchor" href="#what-the-benchmark-reports" aria-label="Permalink to &quot;What the benchmark reports&quot;">​</a></h2><p>For each attachment, the protocol records:</p><ul><li>task outcome and completion time;</li><li>attempts and regrasps;</li><li>prehensile or non-prehensile strategy;</li><li>last completed stage for composed tasks; and</li><li>one primary failure cause for unsuccessful trials.</li></ul><p>HiveBoard is intended to characterize task performance and failure modes. The validation protocol does not, by itself, define a universal ranking of platforms or control interfaces.</p><h2 id="repository-files" tabindex="-1">Repository files <a class="header-anchor" href="#repository-files" aria-label="Permalink to &quot;Repository files&quot;">​</a></h2><p>The current files are maintained in the <a href="https://github.com/EESC-LabRoM/HiveBoard" target="_blank" rel="noreferrer">HiveBoard parts and protocol repository</a>:</p><ul><li><code>STL/</code> — printable parts;</li><li><code>CAD/</code> — editable source geometry;</li><li><code>Simulation/</code> — URDF and USD assets;</li><li><code>Documentation/</code> — protocol and trial templates.</li></ul>',21)])])}const f=t(s,[["render",n]]);export{b as __pageData,f as default};
